import SwiftUI

@MainActor
final class OrderListModel: ObservableObject {
    @Published private(set) var state: State = .loading

    enum State {
        case loading
        case loaded([Order])
        case failed(String)
    }

    private let api: OrdersAPI

    init(api: OrdersAPI) { self.api = api }

    func load() async {
        state = .loading
        do {
            // Suspends here; the actor is released, so the UI keeps drawing.
            let orders = try await api.fetchOrders()
            state = .loaded(orders)
        } catch is CancellationError {
            // The view went away. Not an error, and not worth showing.
            return
        } catch {
            state = .failed(error.localizedDescription)
        }
    }
}

struct OrderListView: View {
    @StateObject private var model: OrderListModel

    var body: some View {
        content
            // .task, not .onAppear + Task: this cancels automatically when the
            // view disappears, which is what stops a fast scroll queueing work.
            .task { await model.load() }
    }
}
